    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address _owner) internal {
        vm.assume(_owner != address(0));
        bool reverted;
        bool returned;
        try c.setOwner(_owner) returns (bool success) {
            returned = success;
            reverted = false;
        } catch {
            returned = false;
            reverted = true;
